#!/bin/sh
# 同名文件让 `make clean` 静默跳过：.PHONY 的必要性
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > Makefile << 'EOF'
CC := D:/mingw64/bin/gcc.exe
CFLAGS := -std=c11 -O2
TARGET := app.exe
OBJS := main.o util.o

$(TARGET): $(OBJS)
	$(CC) $(CFLAGS) -o $@ $^

%.o: %.c
	$(CC) $(CFLAGS) -c $< -o $@

clean:
	@rm -f $(TARGET) $(OBJS)
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > util.h << 'EOF'
int add(int a, int b);
EOF

mingw32-make
ls *.o app.exe 2>/dev/null || true
touch clean             # 制造一个与目标同名的文件
mingw32-make clean       # 被静默跳过：返回 0，但什么都没删
ls *.o app.exe          # 产物都还在！
printf '.PHONY: clean\n' >> Makefile   # 补上 .PHONY
